package com.brightloop.quotation;
import com.brightloop.catalog.*;import com.brightloop.discount.*;import com.brightloop.notification.EmailNotificationService;import com.brightloop.plan.Plan;import com.brightloop.plan.PlanRepository;import com.brightloop.subscription.SubscriptionService;import com.brightloop.tax.*;import java.math.*;import java.time.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service public class QuotationService{
 private final QuotationRepository quotes;private final CustomerRepository customers;private final ProductRepository products;private final ProductVariantRepository variants;private final PlanRepository plans;private final TaxRepository taxes;private final DiscountRepository discounts;private final SubscriptionService subscriptions;private final QuotationTemplateService templates;private final EmailNotificationService emails;
 public QuotationService(QuotationRepository q,CustomerRepository c,ProductRepository p,ProductVariantRepository v,PlanRepository pl,TaxRepository t,DiscountRepository d,SubscriptionService s,QuotationTemplateService templates,EmailNotificationService emails){quotes=q;customers=c;products=p;variants=v;plans=pl;taxes=t;discounts=d;subscriptions=s;this.templates=templates;this.emails=emails;}
 @Transactional(readOnly=true) public List<QuotationDtos.Response> list(){return quotes.findAll().stream().sorted(Comparator.comparing(Quotation::getId).reversed()).map(QuotationDtos.Response::of).toList();}
 @Transactional(readOnly=true) public QuotationDtos.Response get(Long id){return QuotationDtos.Response.of(find(id));}
 @Transactional public QuotationDtos.Response create(QuotationDtos.Request r){return persist(null,r);}
 @Transactional public QuotationDtos.Response createFromTemplate(Long templateId,Long customerId,String discountCode,String paymentTerms,String notes){var template=templates.find(templateId);var lines=template.getLines().stream().map(l->new QuotationDtos.LineRequest(l.getProductId(),l.getPlanId(),l.getVariantId(),l.getQuantity())).toList();return persist(null,new QuotationDtos.Request(customerId,template.getValidityDays(),paymentTerms,notes,discountCode,lines));}
 @Transactional public QuotationDtos.Response update(Long id,QuotationDtos.Request r){Quotation q=find(id);if(!"DRAFT".equals(q.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Only draft quotations can be edited");return persist(q,r);}
 private QuotationDtos.Response persist(Quotation existing,QuotationDtos.Request r){var customer=customers.findById(r.customerId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Customer not found"));Discount discount=discount(r.discountCode());LocalDate today=LocalDate.now();List<Calculated> calc=new ArrayList<>();BigDecimal subtotal=BigDecimal.ZERO,taxTotal=BigDecimal.ZERO;for(var line:r.lines()){Product p=products.findById(line.productId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));Plan plan=line.planId()==null?null:plans.findById(line.planId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Plan not found"));if(plan!=null&&!plan.getProduct().getId().equals(p.getId()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Plan is linked to a different product");ProductVariant variant=line.variantId()==null?null:variants.findById(line.variantId()).filter(v->v.getProduct().getId().equals(p.getId())).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Variant does not belong to this product"));BigDecimal unit=(plan==null?p.getSalesPrice():plan.getBillingPrice()).add(variant==null?BigDecimal.ZERO:variant.getAdditionalPrice());BigDecimal base=unit.multiply(BigDecimal.valueOf(line.quantity())).setScale(2,RoundingMode.HALF_UP);TaxCalc tax=calculateTax(p.getId(),base,line.quantity(),today);subtotal=subtotal.add(base);taxTotal=taxTotal.add(tax.amount);calc.add(new Calculated(p,plan,variant,line.quantity(),unit,tax.rate,base,tax.amount,base.add(tax.amount)));}BigDecimal discAmount=discount==null?BigDecimal.ZERO:("PERCENTAGE".equals(discount.getDiscountType())?subtotal.multiply(discount.getValue()).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP):discount.getValue()).min(subtotal);BigDecimal total=subtotal.add(taxTotal).subtract(discAmount).max(BigDecimal.ZERO);Quotation q=existing;if(q==null){q=new Quotation("QT-"+today.getYear()+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(),customer,today,today.plusDays(r.validityDays()),r.paymentTerms(),r.notes(),discount,subtotal,discAmount,taxTotal,total);}else{q.revise(customer,today,today.plusDays(r.validityDays()),r.paymentTerms(),r.notes(),discount,subtotal,discAmount,taxTotal,total);q.getLines().clear();}for(var c:calc)q.addLine(new QuotationLine(q,c.product,c.plan,c.variant,c.qty,c.unit,c.rate,c.base,c.tax,c.total));return QuotationDtos.Response.of(quotes.save(q));}
 @Transactional public QuotationDtos.Response action(Long id,String action){Quotation q=find(id);try{switch(action){case "send"->{q.markSent();emails.quotation(q.getCustomer().getEmail(),q.getQuotationNumber(),q.getGrandTotal().toPlainString());}case "confirm"->q.confirm();default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unknown quotation action");}}catch(IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}return QuotationDtos.Response.of(q);}
 @Transactional public com.brightloop.subscription.SubscriptionDtos.Response convert(Long id){Quotation q=find(id);try{if(q.getStatus().equals("DRAFT")||q.getStatus().equals("SENT"))q.confirm();var subscription=subscriptions.fromQuotation(q);q.converted();return subscription;}catch(IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}}
 private TaxCalc calculateTax(Long product,BigDecimal base,int quantity,LocalDate date){BigDecimal amount=BigDecimal.ZERO,rate=BigDecimal.ZERO;for(Tax t:taxes.findAll()){if(!t.isActive()||t.getProduct()!=null&&!t.getProduct().getId().equals(product)||t.getEffectiveStart()!=null&&date.isBefore(t.getEffectiveStart())||t.getEffectiveEnd()!=null&&date.isAfter(t.getEffectiveEnd()))continue;if("PERCENTAGE".equals(t.getTaxType())){rate=rate.add(t.getRate());amount=amount.add(base.multiply(t.getRate()).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP));}else amount=amount.add(t.getRate().multiply(BigDecimal.valueOf(quantity)));}return new TaxCalc(amount,rate);}
 private Discount discount(String code){if(code==null||code.isBlank())return null;Discount d=discounts.findByCodeIgnoreCase(code.trim()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Discount code is invalid"));if(!d.eligible(LocalDate.now()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Discount is not currently eligible");return d;}private Quotation find(Long id){return quotes.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Quotation not found"));}private record TaxCalc(BigDecimal amount,BigDecimal rate){}private record Calculated(Product product,Plan plan,ProductVariant variant,int qty,BigDecimal unit,BigDecimal rate,BigDecimal base,BigDecimal tax,BigDecimal total){}
}
